import{_ as n,a0 as l,w as p,s,I as o,x as t,a1 as a,A as i,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Calibre 1.6 正式发布：更方便的标记图书功能 | LCTT x X-CMD","titleTemplate":false,"description":"Calibre 1.6 正式发布：更方便的标记图书功能 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Calibre 1.6 正式发布：更方便的标记图书功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Calibre 1.6 正式发布：更方便的标记图书功能 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Calibre 1.6 released with handy mark-book feature","title":"Calibre 1.6 正式发布：更方便的标记图书功能","tag":"201310","desc":""},"relativePath":"201310/Calibre 1.6 released with handy mark-book feature.md","filePath":"[post].md"}'),b={name:"201310/Calibre 1.6 released with handy mark-book feature.md"};function d(m,e,g,C,f,k){const r=l("Link");return p(),s("div",null,[e[13]||(e[13]=o("h1",{id:"calibre-1-6-正式发布-更方便的标记图书功能",tabindex:"-1"},[t("Calibre 1.6 正式发布：更方便的标记图书功能 "),o("a",{class:"header-anchor",href:"#calibre-1-6-正式发布-更方便的标记图书功能","aria-label":"Permalink to “Calibre 1.6 正式发布：更方便的标记图书功能”"},"​")],-1)),o("p",null,[a(r,{href:"http://calibre-ebook.com/"},{default:i(()=>[...e[0]||(e[0]=[t("Calibre",-1)])]),_:1}),e[1]||(e[1]=t("是一个免费的开源电子图书馆管理工具，令人心动的设计思想，综合了电子书相关范畴的要求和需求，提供了强大的转换处理，专注于电子书的阅读，轻而易举的创建和管理书库，集成在线服务等，总而言之，给你真真正正的现代化电子书阅读体验。",-1))]),e[14]||(e[14]=u(`<p>Calibre 已经更新到<strong>1.6</strong>版本，已有的<strong>标记图书</strong>（book-marking）功能，做了大量的修补和功能增强。</p><p><strong>标记图书</strong>作为一种<strong>暂定</strong>选书的简便方式（重启Calibre后就会失去标记），允许用户标记某本图书，再点击已标记的图书便取消该标记，该特性能在很多场景提供便利。</p><p>最新实现的标记图书功能并没有默认开启，当然，开启它也是很容易的。<code>首选项(Prefences)--&gt;工具栏(Toolbar)--&gt;主工具栏(The main toolbar)--&gt;点击标记图书(Mark Books)--&gt;点击左端的箭头--&gt;应用(Apply)</code>，之后在工具栏上就有图书标记按钮。</p><p>举个例子，<strong>标记</strong>你选择的三本书（按住Ctrl键，并点击选定的三本图书），也可以通过工具栏上的按钮，标记图书。</p><p>最新标记的三本书将显示一个特殊标记的图标，这样用户可以清楚的找到标记的书本。</p><p><img src="http://iloveubuntu.net/pictures_me/calibre%2016%20marking%20books.png" alt=""></p><p>在标记图书后，用户可以通过&#39;右击标记按钮--&gt;显示标记书本&#39;来只显示已标记的图书，同时隐藏未标记的图书。</p><p>在有些时候想清楚观察重点图书，图书标记功能允许用户轻而易举的分离出偏爱的图书，只需要花几秒钟点击标记按钮，即可清楚的展示某本书。</p><p>再次选择标记图书或再点击标记图书按钮，将取消标记，按钮在标记/不标记之间切换。</p><p>Calibre默认携带了好用的电子书阅读器，在1.6版本增加了额外的快捷键配置，意味着现在用户能通过自己的喜好制定不同的<strong>快捷键</strong>例如放大缩小。</p><p>打开电子书阅读器之前先调整快捷键，点击工具条的首选项来设置快捷键，双击一个条目进行编辑。</p><p><img src="http://iloveubuntu.net/pictures_me/calibre%20font%20size%20shortcut.png" alt=""></p><p>以上提及的特性，连同大量的bug的修补、增加了最新的新闻源（一些的乌拉圭的新闻）和改进了一些新闻源（国家地理杂志，纽约书评，聚焦，Carta Capital，Ming Pao，Neu Osnabrucker Zeitung），去感受更强大的Calibre吧!</p><p>###我们怎么<strong>安装</strong>Calibre 1.6呢?</p><p>复制以下命令到终端</p><pre><code>sudo python -c &quot;import sys; py3 = sys.version_info[0] &gt; 2; u = __import__(&#39;urllib.request&#39; if py3 else &#39;urllib&#39;, fromlist=1); exec(u.urlopen(&#39;http://status.calibre-ebook.com/linux_installer&#39;).read()); main()&quot;
</code></pre><p>按回车键，出现<code>Enter the installation directory for calibre [/opt]</code>再按回车键</p><p>如果用户通过PPA安装了Calibre，那么请先执行下列命令（在执行以上命令之前）。</p><pre><code>sudo apt-get remove calibre calibre-bin
</code></pre><hr>`,20)),o("p",null,[e[3]||(e[3]=t("via: ",-1)),a(r,{href:"http://iloveubuntu.net/calibre-16-released-handy-mark-book-feature"},{default:i(()=>[...e[2]||(e[2]=[t("http://iloveubuntu.net/calibre-16-released-handy-mark-book-feature",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("译者：",-1)),a(r,{href:"https://github.com/Luoxcat"},{default:i(()=>[...e[4]||(e[4]=[t("Luoxcat",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),a(r,{href:"https://github.com/jasminepeng"},{default:i(()=>[...e[5]||(e[5]=[t("jasminepeng",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创翻译，",-1)),a(r,{href:"http://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const h=n(b,[["render",d]]);export{_ as __pageData,h as default};
